from itertools import combinations
from fractions import Fraction
import json

LOW=(2,2,0,0); UP=(4,4,4,4)

def wt(p): return sum(p)
def valid(p): return len(p)==4 and all(p[i]>=p[i+1] for i in range(3)) and all(LOW[i]<=p[i]<=UP[i] for i in range(4))
def parts(n, mx=4, k=4):
    out=[]
    def rec(a,last,left):
        if len(a)==k:
            if left==0 and valid(tuple(a)): out.append(tuple(a))
            return
        for x in range(min(last,mx,left),-1,-1): rec(a+[x],x,left-x)
    rec([],mx,n)
    return out

def conj(p): return tuple(sum(x>=c for x in p) for c in range(1,5))
def hstrip(lam,mu):
    if any(lam[i]>mu[i] for i in range(4)): return False
    cl,cm=conj(lam),conj(mu)
    return all(0<=cm[c]-cl[c]<=1 for c in range(4))
def det(A):
    n=len(A)
    if n==0:return 1
    a=[list(map(int,r)) for r in A]; sign=1; prev=1
    for k in range(n-1):
        q=next((i for i in range(k,n) if a[i][k]),None)
        if q is None:return 0
        if q!=k:a[k],a[q]=a[q],a[k];sign=-sign
        piv=a[k][k]
        for i in range(k+1,n):
            for j in range(k+1,n): a[i][j]=(a[i][j]*piv-a[i][k]*a[k][j])//prev
        prev=piv
        for i in range(k+1,n): a[i][k]=0
    return sign*a[-1][-1]
def inv_unimod(A):
    n=len(A)
    if n==0:return []
    x=[[Fraction(v) for v in row]+[Fraction(int(i==j)) for j in range(n)] for i,row in enumerate(A)]
    for k in range(n):
        q=next(i for i in range(k,n) if x[i][k])
        x[k],x[q]=x[q],x[k]
        z=x[k][k]; x[k]=[v/z for v in x[k]]
        for i in range(n):
            if i!=k:
                z=x[i][k]; x[i]=[x[i][j]-z*x[k][j] for j in range(2*n)]
    return [[int(v) for v in row[n:]] for row in x]
def mm(a,b): return [[sum(a[i][k]*b[k][j] for k in range(len(b))) for j in range(len(b[0]))] for i in range(len(a))] if a and b else ([] if a else [[] for _ in range(len(a))])
def rowmul(a,b): return [sum(a[k]*b[k][j] for k in range(len(a))) for j in range(len(b[0]))] if b else []
def find_minor(M,D):
    q=len(D)
    if q==0:return []
    # lexicographic exhaustive finite search; no Smith/invariant computation.
    for I in combinations(range(len(M)),q):
        U=[[M[i][j] for j in D] for i in I]
        if abs(det(U))==1:return list(I)
    raise RuntimeError('no unimodular complementary minor')

records=[]
for d in range(4,17):
    C=parts(d)
    rows=[]; labels=[]
    for t in range(1,5):
        for lam in parts(d-t):
            v=[int(hstrip(lam,mu)) for mu in C]
            rows.append(v); labels.append({'hDegree':t,'source':list(lam)})
    if d<=8:
        B=[i for i,p in enumerate(C) if p[0]==2 and p[1]==2 and p[2]<=2 and p[3]<=2]
    else:B=[]
    D=[i for i in range(len(C)) if i not in B]
    P=find_minor(rows,D)
    U=[[rows[i][j] for j in D] for i in P]
    du=det(U)
    UI=inv_unimod(U)
    AP=[[rows[i][j] for j in B] for i in P]
    residual=[]
    for i,r in enumerate(rows):
        if i not in P:
            left=[r[j] for j in B]
            right=rowmul(rowmul([r[j] for j in D],UI),AP)
            residual.append({'rowIndex':i+1,'vector':[left[j]-right[j] for j in range(len(B))]})
    assert all(all(x==0 for x in z['vector']) for z in residual)
    records.append({'degree':d,'orderedColumns':[list(x) for x in C],'B_indices_one_based':[i+1 for i in B],'B':[list(C[i]) for i in B],'D_indices_one_based':[i+1 for i in D],'completeLabelledRows':[{'index':i+1,**labels[i],'vector':rows[i]} for i in range(len(rows))],'P_indices_one_based':[i+1 for i in P],'U':U,'detU':du,'residuals':residual,'smithDerivedFromBlock':([1]*len(D)+[0]*len(B))})
# Explicit boundary semantics.
out={'parameters':{'i':2,'j':2,'p':2,'c':2,'lower':list(LOW),'upper':list(UP)},'ordering':'columns: reverse lexicographic partitions padded to length 4; rows: hDegree=1,2,3,4 then the same order on source partitions','pieriRule':'entry(t,lambda;mu)=1 iff mu/lambda is a horizontal t-strip, equivalently lambda_i<=mu_i and 0<=mu_prime_c-lambda_prime_c<=1 for i,c=1..4; otherwise 0','blockIdentity':'For each nonselected row r, residual(r)=M[r,B]-M[r,D] U^{-1} M[P,B]=0. U=M[P,D].','degree4EmptyWitness':{'M4':'0x1','D4':'0x0','B4_indices_one_based':[1],'P4':[],'U4':'I_0=[]','detU4':1,'residuals':[]},'records':records,'derivedSmithTable':[{'degree':z['degree'],'diagonal':z['smithDerivedFromBlock'],'quotientFreeBasisColumnIndices':z['B_indices_one_based'],'quotientFreeRank':len(z['B_indices_one_based']),'torsion':[]} for z in records]}
print(json.dumps(out,separators=(',',':')))
